package io.esrest.jdbc;

import java.util.regex.Pattern;

/**
 * Rewrites SQL generated by tools into something Elasticsearch SQL accepts. Currently: {@code SELECT t.* FROM idx t}
 * becomes {@code SELECT * FROM idx t} (ES SQL queries a single index, so the qualifier is redundant).
 * String literals and comments are left untouched.
 */
final class SqlRewriter {
    /** Qualified star such as {@code t.*} or {@code "t".*}, which Elasticsearch SQL rejects. */
    private static final Pattern QUALIFIED_STAR = Pattern.compile("(?:\"(?:[^\"]|\"\")+\"|[A-Za-z_@][\\w@]*)\\s*\\.\\s*\\*");

    private SqlRewriter() { }

    static String rewrite(String sql) {
        StringBuilder result = new StringBuilder(sql.length());
        int codeStart = 0;
        int position = 0;
        while (position < sql.length()) {
            int skippedEnd = endOfLiteralOrComment(sql, position);
            if (skippedEnd < 0) {
                position++;
                continue;
            }
            result.append(rewriteCode(sql.substring(codeStart, position)));
            result.append(sql, position, skippedEnd);
            position = skippedEnd;
            codeStart = skippedEnd;
        }
        result.append(rewriteCode(sql.substring(codeStart)));
        return result.toString();
    }

    private static String rewriteCode(String code) {
        return QUALIFIED_STAR.matcher(code).replaceAll("*");
    }

    /** End index of the string literal or comment starting at {@code start}, or -1 if none starts there. */
    private static int endOfLiteralOrComment(String sql, int start) {
        if (sql.startsWith("--", start)) {
            int lineEnd = sql.indexOf('\n', start);
            return lineEnd < 0 ? sql.length() : lineEnd;
        }
        if (sql.startsWith("/*", start)) {
            int commentEnd = sql.indexOf("*/", start + 2);
            return commentEnd < 0 ? sql.length() : commentEnd + 2;
        }
        if (sql.charAt(start) != '\'') {
            return -1;
        }

        int position = start + 1;
        while (position < sql.length()) {
            if (sql.charAt(position) != '\'') {
                position++;
                continue;
            }
            boolean escapedQuote = position + 1 < sql.length() && sql.charAt(position + 1) == '\'';
            if (!escapedQuote) {
                return position + 1;
            }
            position += 2;
        }
        return sql.length();
    }
}
